PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?zone ?zoneName ?point ?pointName ?tsId WHERE {
  ?zone a brick:Zone ; rdfs:label ?zoneName .
  FILTER(?zoneName = "DataCenter_bot_ZN_6")
  ?point brick:isPointOf ?zone .
  OPTIONAL{ ?point rdfs:label ?pointName }
  ?point ref:hasTimeseriesId ?tsId .
}

